            "svg": "<svg viewBox=\"0 0 1100 1100\" class=\"lesson-visual\"><rect x=\"0\" y=\"0\" width=\"1100\" height=\"1100\" fill=\"#1a1a2e\"/><text x=\"550\" y=\"70\" text-anchor=\"middle\" fill=\"#ffd700\" font-weight=\"bold\" font-size=\"36\">THREE AUTOBIOGRAPHIES</text><text x=\"550\" y=\"115\" text-anchor=\"middle\" fill=\"#888\" font-size=\"24\">A self-portrait across 40 years</text><rect x=\"80\" y=\"170\" width=\"940\" height=\"240\" rx=\"20\" fill=\"rgba(99,102,241,0.12)\" stroke=\"#6366f1\" stroke-width=\"2\"/><text x=\"550\" y=\"215\" text-anchor=\"middle\" fill=\"#6366f1\" font-weight=\"bold\" font-size=\"24\">1845 — NARRATIVE</text><text x=\"550\" y=\"260\" text-anchor=\"middle\" fill=\"#fff\" font-size=\"22\">125 pages, age 27</text><text x=\"550\" y=\"295\" text-anchor=\"middle\" fill=\"#fff\" font-size=\"22\">Witness — proves he is real</text><text x=\"550\" y=\"330\" text-anchor=\"middle\" fill=\"#fff\" font-size=\"22\">Compact, urgent, devastating</text><text x=\"550\" y=\"365\" text-anchor=\"middle\" fill=\"#888\" font-size=\"20\">Garrison preface, not yet legally free</text><text x=\"550\" y=\"395\" text-anchor=\"middle\" fill=\"#888\" font-size=\"20\">Ends in New Bedford</text><rect x=\"80\" y=\"430\" width=\"940\" height=\"240\" rx=\"20\" fill=\"rgba(139,92,246,0.12)\" stroke=\"#8b5cf6\" stroke-width=\"2\"/><text x=\"550\" y=\"475\" text-anchor=\"middle\" fill=\"#8b5cf6\" font-weight=\"bold\" font-size=\"24\">1855 — BONDAGE AND FREEDOM</text><text x=\"550\" y=\"520\" text-anchor=\"middle\" fill=\"#fff\" font-size=\"22\">464 pages, age 37</text><text x=\"550\" y=\"555\" text-anchor=\"middle\" fill=\"#fff\" font-size=\"22\">Political theorist — no white preface</text><text x=\"550\" y=\"590\" text-anchor=\"middle\" fill=\"#fff\" font-size=\"22\">Adds Anna, escape, Garrison split</text><text x=\"550\" y=\"625\" text-anchor=\"middle\" fill=\"#888\" font-size=\"20\">Philosophical, analytical</text><text x=\"550\" y=\"655\" text-anchor=\"middle\" fill=\"#888\" font-size=\"20\">Covey fight expanded</text><rect x=\"80\" y=\"690\" width=\"940\" height=\"240\" rx=\"20\" fill=\"rgba(16,185,129,0.12)\" stroke=\"#10b981\" stroke-width=\"2\"/><text x=\"550\" y=\"735\" text-anchor=\"middle\" fill=\"#10b981\" font-weight=\"bold\" font-size=\"24\">1881/1892 — LIFE AND TIMES</text><text x=\"550\" y=\"780\" text-anchor=\"middle\" fill=\"#fff\" font-size=\"22\">752 pages, age 63 and 74</text><text x=\"550\" y=\"815\" text-anchor=\"middle\" fill=\"#fff\" font-size=\"22\">Elder statesman</text><text x=\"550\" y=\"850\" text-anchor=\"middle\" fill=\"#fff\" font-size=\"22\">War, Reconstruction, Marshal, Haiti</text><text x=\"550\" y=\"885\" text-anchor=\"middle\" fill=\"#888\" font-size=\"20\">Settled scores, defensive moments</text><text x=\"550\" y=\"915\" text-anchor=\"middle\" fill=\"#888\" font-size=\"20\">Historically rich, artistically uneven</text><rect x=\"200\" y=\"950\" width=\"700\" height=\"90\" rx=\"20\" fill=\"rgba(255,215,0,0.1)\" stroke=\"#ffd700\" stroke-width=\"2\"/><text x=\"550\" y=\"995\" text-anchor=\"middle\" fill=\"#ffd700\" font-size=\"22\">Blight 2018: read them together</text><text x=\"550\" y=\"1025\" text-anchor=\"middle\" fill=\"#888\" font-size=\"18\">Truth is in the gaps</text></svg>",
